import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, toJob, type JobPayload } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const send = (res: ServerResponse, status: number, body: unknown) => {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
};
const error = (res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]) =>
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
const readBody = async (req: IncomingMessage): Promise<string> => {
  let body = '';
  for await (const chunk of req) {
    body += chunk.toString();
    if (body.length > 100_000) throw new Error('body too large');
  }
  return body;
};

function getJob(id: string) {
  const row = db.prepare('SELECT * FROM jobs WHERE id = ?').get(id);
  return row ? toJob(row as Record<string, unknown>) : null;
}

function validate(value: unknown): { payload?: JobPayload; fields: {field:string;message:string}[] } {
  const fields: {field:string;message:string}[] = [];
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return { fields: [{ field: 'body', message: 'Must be a JSON object.' }] };
  }
  const body = value as Record<string, unknown>;
  for (const key of Object.keys(body)) if (!['input','steps','failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
  if (typeof body.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
  else if (body.input.length < 1 || body.input.length > 1000 || body.input.trim().length === 0) fields.push({ field: 'input', message: 'Must contain 1–1000 characters and not be only whitespace.' });
  const steps = body.steps === undefined ? 5 : body.steps;
  if (!Number.isInteger(steps) || (steps as number) < 1 || (steps as number) > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  const failAttempts = body.failAttempts === undefined ? 0 : body.failAttempts;
  if (!Number.isInteger(failAttempts) || (failAttempts as number) < 0 || (failAttempts as number) > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  if (fields.length) return { fields };
  return { payload: { input: body.input as string, steps: steps as number, failAttempts: failAttempts as number }, fields };
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
  }
  if (pathname === '/') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const row = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as {seen_at:number} | undefined;
    return send(res, 200, { status: 'ok', worker: row && Date.now() - row.seen_at <= 3000 ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (req.method === 'GET') {
      const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all();
      return send(res, 200, { jobs: rows.map(row => toJob(row as Record<string, unknown>)) });
    }
    if (req.method !== 'POST') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) return error(res, 400, 'invalid_request', 'Content-Type must be application/json.', [{field:'Content-Type',message:'Must be application/json.'}]);
    const keyHeader = req.headers['idempotency-key'];
    const key = Array.isArray(keyHeader) ? keyHeader[0] : keyHeader;
    if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) return error(res, 400, 'invalid_request', 'Invalid Idempotency-Key.', [{field:'Idempotency-Key',message:'Must contain 1–128 letters, digits, underscores, or hyphens.'}]);
    let decoded: unknown;
    try { decoded = JSON.parse(await readBody(req)); }
    catch { return error(res, 400, 'invalid_request', 'Request body must be valid JSON.', [{field:'body',message:'Must be valid JSON.'}]); }
    const checked = validate(decoded);
    if (!checked.payload) return error(res, 400, 'invalid_request', 'Request validation failed.', checked.fields);
    const payload = checked.payload;
    const serialized = JSON.stringify(payload);
    if (key !== undefined) {
      db.exec('BEGIN IMMEDIATE');
      try {
        const existing = db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?').get(key) as {payload:string;job_id:string} | undefined;
        if (existing) {
          db.exec('COMMIT');
          if (existing.payload !== serialized) return error(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used for a different payload.');
          const job = getJob(existing.job_id);
          if (job) return send(res, 200, job);
        } else {
          const id = randomUUID(); const now = new Date().toISOString();
          db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at)
            VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?)`).run(id, payload.input, payload.steps, payload.failAttempts, now, now);
          db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, serialized, id);
          db.exec('COMMIT');
          const job = getJob(id); if (job) return send(res, 201, job);
        }
      } catch (e) { db.exec('ROLLBACK'); throw e; }
    }
    const id = randomUUID(); const now = new Date().toISOString();
    db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at)
      VALUES(?, 'queued', ?, ?, ?, 0, 0, ?, ?)`).run(id, payload.input, payload.steps, payload.failAttempts, now, now);
    const job = getJob(id); return send(res, 201, job);
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    let id: string;
    try { id = decodeURIComponent(match[1]); }
    catch { return error(res, 404, 'not_found', 'Job not found.'); }
    const job = getJob(id);
    if (!job) return error(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, job);
  }
  return error(res, 404, 'not_found', 'Route not found.');
});
server.listen(port, () => console.log(`server listening on ${port}`));
const shutdown = () => server.close(() => { db.close(); process.exit(0); });
process.on('SIGTERM', shutdown); process.on('SIGINT', shutdown);

