import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, toJob } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A process may have died between any two steps. Requeue its claimed work on startup.
db.exec('BEGIN IMMEDIATE');
try {
  const nowIso = new Date().toISOString();
  db.prepare(`UPDATE jobs SET status='queued', progress_completed=0, updated_at=?, retry_at=0
    WHERE status='running' AND attempts < 3`).run(nowIso);
  db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL,
    updated_at=?, retry_at=0 WHERE status='running' AND attempts >= 3`).run(nowIso);
  db.exec('COMMIT');
} catch (e) { db.exec('ROLLBACK'); throw e; }

const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?)
  ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(() => { try { heartbeat(); } catch { /* shutdown race */ } }, 1000);

function claim() {
  db.exec('BEGIN IMMEDIATE');
  try {
    const now = Date.now();
    const row = db.prepare(`SELECT * FROM jobs WHERE status='queued' AND retry_at <= ?
      ORDER BY created_at ASC, rowid ASC LIMIT 1`).get(now);
    if (!row) { db.exec('COMMIT'); return null; }
    const job = toJob(row as Record<string, unknown>);
    const updated = db.prepare(`UPDATE jobs SET status='running', attempts=attempts+1,
      progress_completed=0, updated_at=? WHERE id=? AND status='queued'`).run(new Date().toISOString(), job.id);
    db.exec('COMMIT');
    if (Number(updated.changes) !== 1) return null;
    const claimed = db.prepare('SELECT * FROM jobs WHERE id=?').get(job.id);
    return claimed ? toJob(claimed as Record<string, unknown>) : null;
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}

async function runJob(job: ReturnType<typeof claim> & {}): Promise<void> {
  if (!job) return;
  if (job.attempts <= job.failAttempts) {
    if (job.attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed',error='transient failure',result_output=NULL,updated_at=? WHERE id=? AND status='running'`)
        .run(new Date().toISOString(), job.id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued',progress_completed=0,retry_at=?,updated_at=? WHERE id=? AND status='running'`)
        .run(Date.now() + 500, new Date().toISOString(), job.id);
    }
    return;
  }
  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(100);
    db.prepare(`UPDATE jobs SET progress_completed=?,updated_at=? WHERE id=? AND status='running'`)
      .run(completed, new Date().toISOString(), job.id);
  }
  db.prepare(`UPDATE jobs SET status='completed',result_output=?,error=NULL,retry_at=0,updated_at=?
    WHERE id=? AND status='running'`).run(job.input.toUpperCase(), new Date().toISOString(), job.id);
}

console.log('worker started');
try {
  while (!stopping) {
    const job = claim();
    if (job) await runJob(job);
    else await sleep(100);
  }
} finally {
  clearInterval(heartbeatTimer);
  db.close();
}

